import type { PanelSpec } from '../types';
import { PAPER, toggleBase, toggleLever } from '../components.ts';

/**
 * Canopy switch on its stand-off barrel, which angles down off the wall: the
 * barrel's back end (top arc) meets the wall, its lower end face carries the
 * toggle (the shared plain toggle, foreshortened) facing inboard. Drawn solid
 * under the canopy handle and again dashed over it where the handle hides it.
 * Barrel x 981–1044 px, top y 367 px, bottom y 462 px (mv-wall-1).
 */
const canopySwitch = (hidden: boolean) => {
  const [x0, x1, yb, ye, ry] = [332.4, 357.6, 66, 81.6, 11.2], cx = (x0 + x1) / 2, rx = (x1 - x0) / 2;
  const st = hidden ? 'fill="none" stroke-dasharray="1.6 1.2"' : `fill="${PAPER}"`;
  const sw = hidden ? 0.25 : 0.4;
  const body = `<path d="M${x0} ${ye}V${yb}A${rx} ${ry} 0 0 1 ${x1} ${yb}V${ye}" ${st} stroke="#161616" stroke-width="${sw}"/>` +
    `<ellipse cx="${cx}" cy="${ye}" rx="${rx}" ry="${ry}" ${st} stroke="#161616" stroke-width="${sw}"/>`;
  const toggle = `<g transform="translate(${cx} ${ye}) scale(1 ${(ry / rx).toFixed(3)})">${toggleBase('toggle-large') + toggleLever('toggle-large', 0, 3)}</g>`;
  return body + (hidden ? `<g stroke-dasharray="1.6 1.2">${toggle.replace(/ fill="[^"]*"/g, ' fill="none"').replace(/stroke="var\(--panel-paper,#fff\)"/g, 'stroke="none"')}</g>` : toggle);
};

/** Callout magnification for the hidden canopy switch. */
const CALLOUT = 2;
/** Shared plain toggle (centre position, seen front-on), magnified about `at` with pens kept at their drawn widths. */
const calloutToggle = (at: [number, number]) =>
  `<g transform="translate(${at[0]} ${at[1]}) scale(${CALLOUT})">` +
  (toggleBase('toggle-large') + toggleLever('toggle-large', 0, 3)).replace(/stroke-width="([\d.]+)"/g, (_, w) => `stroke-width="${(+w / CALLOUT).toFixed(3)}"`) + '</g>';

/**
 * F-16C left sidewall above the throttle, DCS, drawn square-on to the wall:
 * throttle on its guide rail, CHAFF/FLARE dispense button, and the locked
 * canopy handle with the canopy switch hidden behind its stem (dashed, with a
 * front-on callout).
 *
 * Reference: DCS ModelViewer views square-on to the wall, supplied by Nathan
 * (2026-11-18): mv-wall-1 (handle locked, throttle IDLE), mv-throttle-off
 * (argument 755 = −1) and the rolled-outboard view (755 = −0.884). Drawn in
 * mv-wall-1 pixels and converted at 2.5 px/mm about the crop origin
 * x 150, y 230 px. The guide rail is one circle (centre 585.2, 924 px; slot
 * radius 474 px, outer edge 481.5/492 px) with its bolt lugs square to the
 * tangent. The throttle art is projected from Jonah Tsai's (Hempstick) F-16
 * throttle CAD, registered on the ModelViewer views (CC BY-NC 4.0, credited on
 * the page); the lever pivots at x 578.25, y 950.84 px.
 */

